<?php /** The map form (screen menu-item-map; ids map-form-field-{name}). Data: m, categories, price, back, errors */ $id = (int) $m['menu_item_id']; ?>
<?= view('shared/header.php', ['id' => 'menu-item-map', 'title' => 'Map ' . $m['plu'] . ' · ' . $m['name'], 'crumbs' => [['Home', '/'], ['Menu items', '/menu/'], [$m['name'], '/menu/' . $id], ['Map', null]], 'back' => $back ?? ['/menu/' . $id, 'the menu item']]) ?>
<div class="main-content" id="menu-item-map-content">
    <form method="post" action="/menu/map.php" hx-post="/menu/map.php" hx-target="#flash" class="card" id="map-form"><?= csrf_field() ?><input type="hidden" name="menu_item" value="<?= $id ?>"><?php if (!empty($_GET['back'])): ?><input type="hidden" name="return_to" value="<?= e(safe_local_path($_GET['back']) ?? '') ?>"><?php endif; ?>
        <div class="card-body">
            <?= form_picker('map-form', 'recipe', 'Recipe', 'recipe', $m['recipe_id'], $errors, ['params' => ['kind' => 1], 'help' => 'A menu-item recipe. Clear it to unmap.', 'create' => ['label' => 'New recipe', 'url' => with_back('/recipes/new?kind=menu_item', here_url())]]) ?>
            <div class="row mb-3 align-items-center"><div class="col-lg-4"><label class="fw-semibold" for="map-form-field-portions">Portions per sale</label></div><div class="col-lg-8"><input type="number" step="0.01" min="0.01" name="portions" id="map-form-field-portions" class="form-control btn-touch" value="<?= e(ri_fmt($m['portions'], 2)) ?>"><div class="form-text">A "large" is 1.5 portions of the recipe.</div></div></div>
            <div class="row mb-3 align-items-center"><div class="col-lg-4"><label class="fw-semibold" for="map-form-field-no-depletion">Sells nothing from stock</label></div><div class="col-lg-8"><input type="hidden" name="no_depletion" value="no"><label class="d-flex align-items-center gap-2 border rounded px-3 btn-touch" for="map-form-field-no-depletion"><input type="checkbox" class="form-check-input mt-0" name="no_depletion" value="yes" id="map-form-field-no-depletion" <?= $m['no_depletion'] ? 'checked' : '' ?>>A service charge, a gift card, a delivery fee — leaves the unmapped queue, depletes nothing.</label></div></div>
            <div class="row mb-3 align-items-center"><div class="col-lg-4"><label class="fw-semibold" for="map-form-field-menu-category">Menu category</label></div><div class="col-lg-8"><select name="menu_category" id="map-form-field-menu-category" class="form-select btn-touch"><option value="">None</option><?php foreach ($categories as $c): ?><option value="<?= (int) $c['category_id'] ?>" <?= (string) $m['category_id'] === (string) $c['category_id'] ? 'selected' : '' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></div></div>
            <div class="row mb-3 align-items-center"><div class="col-lg-4"><label class="fw-semibold" for="map-form-field-price">Price at this site</label></div><div class="col-lg-8"><div class="input-group"><span class="input-group-text">$</span><input type="number" step="0.01" min="0" name="price" id="map-form-field-price" class="form-control btn-touch" placeholder="<?= $price !== null ? e(ri_fmt($price, 2)) : 'optional' ?>"></div><div class="form-text">Optional — sets this site's price from today.</div></div></div>
        </div>
        <div class="card-footer d-flex gap-2"><button type="submit" class="btn btn-primary btn-touch" id="map-form-save">Save the map</button><?= hx_link('/menu/' . $id, 'Cancel', 'btn btn-light btn-touch') ?></div>
    </form>
</div>
